/// <summary>
/// AVA/WEN 2024/02/26
/// </summary>
internal final class AVAProdStartService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_contract">AVAProdStartContract</param>
public void process(AVAProdStartContract _contract)
{
    AVATraverseNum      travNum = _contract.parmTraverseNum();
    #OCCRetryCount

    try
    {
        this.startTraverse(travNum);
        this.updateTraverse(travNum);
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

}

private void startTraverse(AVATraverseNum _travNum)
{
    ProdTable           prodTable;
    ProdMultiStartUp    prodMultiStartUp;

    AVATraverseTrans    traverseTrans;

    while select traverseTrans group by ProdId
        where traverseTrans.TravNum == _travNum
            && !traverseTrans.ProcessNum 
    {
        prodTable = ProdTable::find(traverseTrans.ProdId);

        prodMultiStartUp = ProdMultiStartUp::construct(new Args());
        RunBaseMultiParm::initParm(prodMultiStartUp);
        prodMultiStartUp.insert(prodTable, prodMultiStartUp.defaultParmBuffer());

        prodMultiStartUp.runOnServer();
    }
}

private void updateTraverse(AVATraverseNum _travNum)
{
    AVATraverseTrans    traverseTrans;
    Counter             maxProcNum;

    select maxof(ProcessNum) from traverseTrans where traverseTrans.TravNum == _travNum;
    maxProcNum = traverseTrans.ProcessNum;

    while select forupdate traverseTrans where traverseTrans.TravNum == _travNum
            && !traverseTrans.ProcessNum
    {
        ttsbegin;
        traverseTrans.TravStatus = AVATravStatus::InProcess;
        traverseTrans.ProcessNum = maxProcNum + 1;
        traverseTrans.update();
        ttscommit;
    }
}
